/* libphonenumber-js lightweight browser bundle for CarryParcel */
(function(window) {
  'use strict';

  // Country metadata database
  const countryMeta = {
    '+91': { country: 'IN', name: 'India', minLen: 10, maxLen: 10, pattern: /^[6-9]\d{9}$/ },
    '+1':  { country: 'US', name: 'USA/Canada', minLen: 10, maxLen: 10, pattern: /^[2-9]\d{9}$/ },
    '+44': { country: 'GB', name: 'United Kingdom', minLen: 10, maxLen: 10, pattern: /^7\d{9}$/ },
    '+971':{ country: 'AE', name: 'UAE', minLen: 9, maxLen: 9, pattern: /^5\d{8}$/ },
    '+65': { country: 'SG', name: 'Singapore', minLen: 8, maxLen: 8, pattern: /^[89]\d{7}$/ },
    '+61': { country: 'AU', name: 'Australia', minLen: 9, maxLen: 9, pattern: /^4\d{8}$/ },
    '+49': { country: 'DE', name: 'Germany', minLen: 10, maxLen: 11, pattern: /^1[567]\d{8,9}$/ },
    '+33': { country: 'FR', name: 'France', minLen: 9, maxLen: 9, pattern: /^[67]\d{8}$/ }
  };

  function validatePhoneNumber(rawNumber, countryCode) {
    const raw = String(rawNumber || '').trim().replace(/\D/g, '');
    const code = String(countryCode || '+91').trim();
    const meta = countryMeta[code] || { minLen: 8, maxLen: 13, pattern: /^\d{8,13}$/ };

    if (!raw) {
      return { isValid: false, error: 'Mobile number is required.' };
    }

    const isIndia = code === '+91';

    if (isIndia) {
      if (raw.length !== 10) {
        return { isValid: false, error: 'Enter a valid 10-digit Indian mobile number.' };
      }
      if (!meta.pattern.test(raw)) {
        return { isValid: false, error: 'Enter a valid 10-digit Indian mobile number starting with 6, 7, 8, or 9.' };
      }
      return { isValid: true, e164: `+91${raw}`, country: 'IN' };
    }

    if (raw.length < meta.minLen || raw.length > meta.maxLen) {
      return { isValid: false, error: `Enter a valid mobile number for the selected country (${meta.name || code}).` };
    }

    if (meta.pattern && !meta.pattern.test(raw)) {
      return { isValid: false, error: `Enter a valid mobile number for the selected country (${meta.name || code}).` };
    }

    return { isValid: true, e164: `${code}${raw}`, country: meta.country };
  }

  window.CarryParcelPhone = {
    validatePhoneNumber,
    countryMeta
  };
})(window);
